style.css:
@-moz-document domain("instagram.com") {
:root {
    --ig-bg: #1a1524;
    --ig-bg-light: #2b233d;
    --ig-card: #241d36;
    --ig-text: #e0d8ff;
    --ig-muted: #a29bb5;
    --ig-accent: #c7a6ff;
    --ig-border: #3d3352;
  }

  body,
  html {
    background-color: var(--ig-bg) !important;
    color: var(--ig-text) !important;
    font-family: "Poppins", "Inter", sans-serif !important;
  }

  header,
  nav,
  section,
  main,
  aside,
  div[role="dialog"] {
    background-color: var(--ig-card) !important;
    border: 1px solid var(--ig-border) !important;
    border-radius: 12px !important;
  }

  input,
  textarea {
    background-color: var(--ig-bg-light) !important;
    color: var(--ig-text) !important;
    border: 1px solid var(--ig-border) !important;
    border-radius: 10px !important;
  }

  ::placeholder {
    color: var(--ig-muted) !important;
  }

  a, p, span, h1, h2, h3 {
    color: var(--ig-text) !important;
  }

  /* Sidebar Icons */
  nav svg,
  path {
    fill: var(--ig-accent) !important;
  }

  /* Active Sidebar Item */
  nav a:hover,
  nav a[aria-current="page"] {
    background-color: var(--ig-bg-light) !important;
    border-radius: 8px;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-thumb {
    background-color: var(--ig-accent);
    border-radius: 6px;
  }

  ::-webkit-scrollbar-track {
    background-color: var(--ig-bg-light);
  }

  /* Hide Suggestions */
  [aria-label="Suggested for you"],
  [aria-label="Sponsored"] {
    display: none !important;
  }

  /* Buttons */
  button {
    background-color: var(--ig-accent) !important;
    color: var(--ig-bg) !important;
    border-radius: 8px !important;
    border: none !important;
  }

  /* Story circle border fix */
  circle {
    stroke: var(--ig-accent) !important;
  }
}
